'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useId, useState } from 'react';

import {
  CalendarCheckIcon,
  CalendarIcon,
  PlusIcon,
  VideoIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Chip } from '@/registry/ndeko/ui/chip';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Input } from '@/registry/ndeko/ui/input';
import { RadioGroup, RadioGroupItem } from '@/registry/ndeko/ui/radio-group';

import {
  ActionButton,
  useTimedAction,
  type ActionLabels,
} from './_parts/action-button';
import { ChoiceSegments, type SegmentOption } from './_parts/choice-segments';
import { CopyButton } from './_parts/copy-button';
import {
  ModalCloseButton,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { chipVariantsOf } from './_parts/motion';
import {
  CURRENT_USER,
  PEOPLE,
  firstNameOf,
  type Person,
} from './_parts/people';
import { PersonAvatar } from './_parts/person-avatar';
import { Swap } from './_parts/swap';

type Slot = { id: string; day: string; short: string; startMinutes: number };

type Duration = '30' | '45' | '60';

const SLOTS: Slot[] = [
  {
    id: 'tue-1000',
    day: 'Tuesday 10 November',
    short: 'Tue 10',
    startMinutes: 600,
  },
  {
    id: 'tue-1430',
    day: 'Tuesday 10 November',
    short: 'Tue 10',
    startMinutes: 870,
  },
  {
    id: 'wed-0930',
    day: 'Wednesday 11 November',
    short: 'Wed 11',
    startMinutes: 570,
  },
  {
    id: 'thu-1600',
    day: 'Thursday 12 November',
    short: 'Thu 12',
    startMinutes: 960,
  },
];

const DURATIONS: SegmentOption<Duration>[] = [
  { value: '30', label: '30 min' },
  { value: '45', label: '45 min' },
  { value: '60', label: '60 min' },
];

const FIRST_ATTENDEES = ['lucas', 'priya', 'hana'];

const MEETING_LINK = 'meet.lattice.example/prd-review-4821';

const MINUTES_PER_HOUR = 60;

const SCHEDULE_LABELS: ActionLabels = {
  idle: 'Schedule',
  working: 'Scheduling',
  done: 'Scheduled',
};

const SLOT_CHIP = [
  'flex h-7 cursor-pointer items-center gap-1.5 rounded-full bg-card px-3 text-xs font-medium tabular-nums text-muted-foreground',
  'shadow-[0_1px_2px_rgb(0_0_0/0.05)] hairline-ring ring-foreground/12 transition-[color,background-color,box-shadow] duration-150',
  'hover:text-foreground dark:bg-foreground/[0.04]',
  'has-data-checked:bg-primary/10 has-data-checked:text-primary-ink has-data-checked:ring-primary/35',
  'has-focus-visible:ring-[3px] has-focus-visible:ring-ring/25',
].join(' ');

function padded(value: number) {
  return String(value).padStart(2, '0');
}

function clockOf(totalMinutes: number) {
  const hours = Math.floor(totalMinutes / MINUTES_PER_HOUR);
  const minutes = totalMinutes % MINUTES_PER_HOUR;
  return `${padded(hours)}:${padded(minutes)}`;
}

function peopleLineOf(count: number) {
  if (count === 0) {
    return 'just you';
  }
  if (count === 1) {
    return 'with 1 person';
  }
  return `with ${count} people`;
}

function summaryOf(slot: Slot, duration: Duration, attendeeCount: number) {
  const endMinutes = slot.startMinutes + Number(duration);
  const start = clockOf(slot.startMinutes);
  const end = clockOf(endMinutes);
  const people = peopleLineOf(attendeeCount);
  return `${slot.day}, ${start} to ${end}, ${people}`;
}

function slotById(slotId: string) {
  return SLOTS.find((slot) => slot.id === slotId) ?? SLOTS[0];
}

function AttendeeChip({
  person,
  allowsLayout,
  onRemove,
}: {
  person: Person;
  allowsLayout: boolean;
  onRemove: (personId: string) => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const variants = chipVariantsOf(shouldReduceMotion);
  const firstName = firstNameOf(person);

  function remove() {
    onRemove(person.id);
  }

  return (
    <motion.li
      layout={allowsLayout}
      variants={variants}
      initial='hidden'
      animate='shown'
      exit='hidden'
      className='flex'
    >
      <Chip
        color='var(--muted-foreground)'
        className='h-7 gap-1.5 rounded-full pr-0.5 pl-0.5 text-[13px]'
      >
        <Avatar className='size-5 text-[9px]'>
          {person.avatar && <AvatarImage src={person.avatar} alt='' />}
          <AvatarFallback>{person.initials}</AvatarFallback>
        </Avatar>
        {firstName}
        <button
          type='button'
          aria-label={`Remove ${person.name}`}
          onClick={remove}
          className='hover:bg-foreground/10 focus-visible:ring-ring/25 flex size-6 cursor-pointer items-center justify-center rounded-full opacity-70 transition-[opacity,background-color] duration-150 outline-none hover:opacity-100 focus-visible:opacity-100 focus-visible:ring-[3px]'
        >
          <XIcon className='size-3' />
        </button>
      </Chip>
    </motion.li>
  );
}

function AddAttendeeSlot({
  candidates,
  onAdd,
}: {
  candidates: Person[];
  onAdd: (personId: string) => void;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label='Add an attendee'
            className='hairline-border border-foreground/25 text-muted-foreground hover:bg-foreground/[0.03] hover:text-foreground focus-visible:ring-ring/25 data-popup-open:bg-foreground/5 flex size-7 cursor-pointer items-center justify-center rounded-full border-dashed outline-none focus-visible:ring-[3px]'
          />
        }
      >
        <PlusIcon className='size-3.5' />
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-56'>
        <DropdownMenuLabel>Invite to the meeting</DropdownMenuLabel>
        {candidates.map((person) => {
          function add() {
            onAdd(person.id);
          }

          return (
            <DropdownMenuItem key={person.id} onClick={add}>
              <PersonAvatar person={person} size='sm' />
              {person.name}
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function ScheduleContent() {
  const [title, setTitle] = useState('Review the onboarding checklist');
  const [attendeeIds, setAttendeeIds] = useState<string[]>(FIRST_ATTENDEES);
  const [slotId, setSlotId] = useState(SLOTS[0].id);
  const [duration, setDuration] = useState<Duration>('30');
  const { state, run } = useTimedAction();
  const shouldReduceMotion = useReducedMotion();
  const allowsLayout = !shouldReduceMotion;
  const titleId = useId();
  const attendeesId = useId();
  const slotsId = useId();
  const linkId = useId();
  const others = PEOPLE.filter((person) => person.id !== CURRENT_USER.id);
  const attendees = others.filter((person) => attendeeIds.includes(person.id));
  const candidates = others.filter(
    (person) => !attendeeIds.includes(person.id)
  );
  const hasCandidates = candidates.length > 0;
  const slot = slotById(slotId);
  const summary = summaryOf(slot, duration, attendees.length);
  const hasTitle = title.trim().length > 0;
  const hasAttendees = attendees.length > 0;
  const isReady = hasTitle && hasAttendees;
  const isIdle = state === 'idle';
  const isScheduleDisabled = isIdle && !isReady;

  function changeTitle(event: React.ChangeEvent<HTMLInputElement>) {
    setTitle(event.target.value);
  }

  function addAttendee(personId: string) {
    setAttendeeIds((previous) => [...previous, personId]);
  }

  function removeAttendee(personId: string) {
    setAttendeeIds((previous) => previous.filter((id) => id !== personId));
  }

  function changeSlot(value: unknown) {
    const picked = SLOTS.find((candidate) => candidate.id === value);
    if (picked) {
      setSlotId(picked.id);
    }
  }

  function schedule(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!isReady) {
      return;
    }
    run(() => {});
  }

  return (
    <form onSubmit={schedule} className='flex flex-col gap-5'>
      <ModalHeader>
        <ModalTitle>Schedule a meeting</ModalTitle>
        <ModalDescription>
          Everyone gets an invitation with the link and the agenda
        </ModalDescription>
      </ModalHeader>
      <div className='flex flex-col gap-1.5'>
        <label htmlFor={titleId} className='text-[13px] font-medium'>
          Title
        </label>
        <Input id={titleId} value={title} onChange={changeTitle} />
      </div>
      <div className='flex flex-col gap-2'>
        <span id={attendeesId} className='text-[13px] font-medium'>
          Attendees
        </span>
        <ul
          aria-labelledby={attendeesId}
          className='relative flex flex-wrap items-center gap-1.5'
        >
          <AnimatePresence initial={false} mode='popLayout'>
            {attendees.map((person) => (
              <AttendeeChip
                key={person.id}
                person={person}
                allowsLayout={allowsLayout}
                onRemove={removeAttendee}
              />
            ))}
          </AnimatePresence>
          {hasCandidates && (
            <motion.li layout={allowsLayout} className='flex'>
              <AddAttendeeSlot candidates={candidates} onAdd={addAttendee} />
            </motion.li>
          )}
        </ul>
      </div>
      <div className='flex flex-col gap-2'>
        <div className='flex items-baseline justify-between gap-3'>
          <span id={slotsId} className='text-[13px] font-medium'>
            Next free slots for everyone
          </span>
          <span className='text-muted-foreground text-xs'>Your time, CET</span>
        </div>
        <RadioGroup
          aria-labelledby={slotsId}
          value={slotId}
          onValueChange={changeSlot}
          className='flex flex-wrap gap-1.5'
        >
          {SLOTS.map((candidate) => (
            <label key={candidate.id} className={SLOT_CHIP}>
              <RadioGroupItem value={candidate.id} className='sr-only' />
              {`${candidate.short} · ${clockOf(candidate.startMinutes)}`}
            </label>
          ))}
        </RadioGroup>
      </div>
      <div className='flex flex-col gap-2'>
        <span className='text-[13px] font-medium'>Duration</span>
        <ChoiceSegments
          label='Duration'
          value={duration}
          options={DURATIONS}
          onValueChange={setDuration}
        />
      </div>
      <div className='flex flex-col gap-1.5'>
        <label htmlFor={linkId} className='text-[13px] font-medium'>
          Meeting link
        </label>
        <div className='flex items-center gap-2'>
          <div className='relative min-w-0 flex-1'>
            <VideoIcon className='text-muted-foreground pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2' />
            <Input
              id={linkId}
              readOnly
              value={MEETING_LINK}
              className='text-muted-foreground pl-8'
            />
          </div>
          <CopyButton
            text={`https://${MEETING_LINK}`}
            size='icon'
            aria-label='Copy the meeting link'
            announcement='Meeting link copied'
          />
        </div>
      </div>
      <p className='flex items-start gap-2 text-[13px]'>
        <CalendarIcon className='text-muted-foreground mt-0.5 size-4 shrink-0' />
        <Swap swapKey={summary} kind='label'>
          {summary}
        </Swap>
      </p>
      <ModalFooter>
        <ModalCloseButton type='button' variant='ghost'>
          Cancel
        </ModalCloseButton>
        <ActionButton
          type='submit'
          state={state}
          labels={SCHEDULE_LABELS}
          idleIcon={<CalendarCheckIcon />}
          disabled={isScheduleDisabled}
        />
      </ModalFooter>
    </form>
  );
}

export default function Modal10() {
  return (
    <ModalPreview triggerLabel='Open schedule a meeting' size='md'>
      <ScheduleContent />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

export type ActionState = 'idle' | 'working' | 'done';

export type ActionLabels = Record<ActionState, string>;

const WORKING_MS = 800;

const DONE_MS = 1600;

/** The life of an action that takes a moment: working, then done for a beat, then ready again. The change is committed when the work ends. */
export function useTimedAction() {
  const [state, setState] = useState<ActionState>('idle');
  const commitRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (state === 'working') {
      const timeout = window.setTimeout(() => {
        const commit = commitRef.current;
        commitRef.current = null;
        if (commit) {
          commit();
        }
        setState('done');
      }, WORKING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'done') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, DONE_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function run(commit: () => void) {
    if (state !== 'idle') {
      return;
    }
    commitRef.current = commit;
    setState('working');
  }

  const isBusy = state !== 'idle';

  return { state, run, isBusy };
}

function iconOf(state: ActionState, idleIcon: React.ReactNode) {
  if (state === 'working') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'done') {
    return <CheckIcon />;
  }
  return idleIcon;
}

type ActionButtonProps = Omit<ButtonProps, 'children'> & {
  state: ActionState;
  labels: ActionLabels;
  idleIcon?: React.ReactNode;
};

/** One button that becomes its next state: its icon swaps, its label crossfades and its width follows the new label. */
export function ActionButton({
  state,
  labels,
  idleIcon,
  ...props
}: ActionButtonProps) {
  const icon = iconOf(state, idleIcon);
  const hasIcon = Boolean(icon);
  const label = labels[state];
  const isWorking = state === 'working';
  const isDone = state === 'done';

  return (
    <>
      <Button aria-busy={isWorking} {...props}>
        {hasIcon && <Swap swapKey={state}>{icon}</Swap>}
        <AnimatedSize axis='width' as='span'>
          <Swap swapKey={label} kind='label'>
            {label}
          </Swap>
        </AnimatedSize>
      </Button>
      <span className='sr-only' role='status'>
        {isDone && labels.done}
      </span>
    </>
  );
}

'use client';

import type { Icon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

export type SegmentOption<Value extends string> = {
  value: Value;
  label: string;
  icon?: Icon;
};

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

type ChoiceSegmentsProps<Value extends string> = {
  value: Value;
  options: SegmentOption<Value>[];
  onValueChange: (value: Value) => void;
  /** Names the group for screen readers when no visible label points at it. */
  label: string;
  className?: string;
};

/** One choice out of a few on a segmented track: a raised thumb travels to the picked segment. */
export function ChoiceSegments<Value extends string>({
  value,
  options,
  onValueChange,
  label,
  className,
}: ChoiceSegmentsProps<Value>) {
  const pressedValues = [value];

  function changeValue(nextValues: unknown[]) {
    const [nextValue] = nextValues;
    const option = options.find((candidate) => candidate.value === nextValue);
    if (option) {
      onValueChange(option.value);
    }
  }

  return (
    <ToggleGroup
      aria-label={label}
      value={pressedValues}
      onValueChange={changeValue}
      travel
      size='sm'
      indicatorClassName={THUMB}
      className={cn('bg-foreground/[0.05] w-full rounded-lg p-0.5', className)}
    >
      {options.map((option) => {
        const OptionGlyph = option.icon;

        return (
          <ToggleGroupItem
            key={option.value}
            value={option.value}
            className='flex-1 rounded-md'
          >
            {OptionGlyph && <OptionGlyph />}
            {option.label}
          </ToggleGroupItem>
        );
      })}
    </ToggleGroup>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { CheckIcon, CopyIcon, LinkIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

const COPIED_RESET_MS = 1600;

/** Copies a text and says so for a moment. */
export function useCopy(text: string) {
  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    if (!isCopied) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setIsCopied(false);
    }, COPIED_RESET_MS);
    return () => window.clearTimeout(timeout);
  }, [isCopied]);

  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
    } catch {
      setIsCopied(false);
    }
  }

  return { isCopied, copy };
}

type CopyGlyph = 'copy' | 'link';

function glyphOf(isCopied: boolean, glyph: CopyGlyph) {
  if (isCopied) {
    return <CheckIcon className='text-success-foreground' />;
  }
  if (glyph === 'link') {
    return <LinkIcon />;
  }
  return <CopyIcon />;
}

function labelOf(isCopied: boolean, label: string, copiedLabel: string) {
  if (isCopied) {
    return copiedLabel;
  }
  return label;
}

type CopyButtonProps = Omit<ButtonProps, 'children' | 'onClick'> & {
  text: string;
  /** Visible label. Leave it out for an icon button, and give `aria-label` instead. */
  label?: string;
  copiedLabel?: string;
  /** Announced once the text is on the clipboard. */
  announcement: string;
  glyph?: CopyGlyph;
};

/** A copy action whose icon becomes a check and whose label becomes Copied, then returns. */
export function CopyButton({
  text,
  label,
  copiedLabel = 'Copied',
  announcement,
  glyph = 'copy',
  variant = 'outline',
  size = 'sm',
  ...props
}: CopyButtonProps) {
  const { isCopied, copy } = useCopy(text);
  const icon = glyphOf(isCopied, glyph);
  const iconKey = String(isCopied);
  const hasLabel = Boolean(label);
  const shownLabel = labelOf(isCopied, label ?? '', copiedLabel);

  return (
    <>
      <Button variant={variant} size={size} onClick={copy} {...props}>
        <Swap swapKey={iconKey}>{icon}</Swap>
        {hasLabel && (
          <AnimatedSize axis='width' as='span'>
            <Swap swapKey={shownLabel} kind='label'>
              {shownLabel}
            </Swap>
          </AnimatedSize>
        )}
      </Button>
      <span className='sr-only' role='status'>
        {isCopied && announcement}
      </span>
    </>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

